import json,collections,pathlib
root=pathlib.Path.cwd()
q=json.loads((root/'src/data/questions.json').read_text());p=json.loads((root/'src/lab/data/problems.json').read_text());c=json.loads((root/'src/data/concepts.json').read_text());e=json.loads((root/'src/data/edges.json').read_text())
report={'kind':'software/content structural audit; no participant data','depth_map':{'questions':len(q),'domains':dict(collections.Counter(x['domain'] for x in q)),'assessment_items':sum(x['assessment'] for x in q),'duplicate_prompts':len(q)-len(set(x['prompt'] for x in q)),'answer_key_positions':dict(collections.Counter(x['correctIndex'] for x in q if 'correctIndex' in x)),'examples_per_item':dict(collections.Counter(len(x['sampleAnchors']) for x in q)),'concepts':len(c),'edges':len(e)},'reasoning_lab':{'items':len(p),'pools':dict(collections.Counter(x['pool'] for x in p)),'propositions_per_item':dict(collections.Counter(len(x['propositions']) for x in p)),'argument_kinds':dict(collections.Counter(a['kind'] for x in p for a in x['arguments'])),'admitted_objections_declared_refuting':sum(o['refutesWhenAdmitted'] for x in p for o in x['objections']),'grounding_patterns':dict(collections.Counter(','.join(a['id'] for a in x['propositions'] if a['grounded']) for x in p))}}
(root/'research/audits/2026-10-11-content-counts.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
